-- Generated X repair maintenance guards.
CREATE TRIGGER maintenance_x_post_repair_work_insert BEFORE INSERT ON "x_post_repair_work" WHEN EXISTS(SELECT 1 FROM content_transitions t WHERE t.generation=(SELECT max(generation) FROM content_transitions) AND t.maintenance_state='stopped' AND NOT EXISTS(SELECT 1 FROM content_transition_permits p WHERE p.transition_id=t.id AND ((p.mode='baseline' AND t.local_site=t.target_site AND t.phase IN ('prepared','target_ingress_ready','source_fenced')) OR (p.mode='archive' AND t.local_site=t.source_site AND t.phase='source_fenced')))) BEGIN SELECT RAISE(ABORT,'content_transition_maintenance_stopped'); END;
--> statement-breakpoint
